INSERT IGNORE INTO permissions(permission_key,description)VALUES('payments.create','Submit student payment requests'),('profile.manage','Manage own profile');
INSERT IGNORE INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Registrar' AND p.permission_key='finance.manage';
INSERT IGNORE INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Staff' AND p.permission_key='finance.manage';
INSERT IGNORE INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_name='Student' AND p.permission_key='payments.create';
INSERT IGNORE INTO role_permissions(role_id,permission_id)SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.role_name IN('Admin','Registrar','Staff','Teacher','Student') AND p.permission_key='profile.manage';
